        "bodyRu": "Вознесенский кафедральный собор стоит внутри парка Панфиловцев и заметен благодаря выразительному фасаду. Знакомство с ним удобно начинать с внешнего осмотра: отойдите на достаточное расстояние, чтобы увидеть здание целиком, затем рассмотрите детали. Это действующий храм, поэтому внутреннее посещение зависит от церковной жизни и доступности помещений, а не только от туристического расписания.\n\nВнутри следует говорить тихо, не перекрывать проходы и не мешать молитве. Для фотосъёмки и группового осмотра сначала уточните правила. Расписание богослужений публикуется отдельно на сайте собора; наличие службы не означает, что в это время можно свободно проводить экскурсию. Если посетить интерьер не получится, внешний осмотр всё равно остаётся полноценной частью городской прогулки.\n\nОриентировочно заложите 30–60 минут без участия в богослужении. Это редакционная оценка. Собор хорошо сочетается с аллеями парка и музеем Ыхласа. Адрес на улице Гоголя относится к храму, а не к любому входу в парк: при встрече с водителем покажите именно карточку собора.",
