            "ko": "공원 산책길에서 건물 전체를 바라본 뒤 가까이 다가가 외관의 장식을 살펴보세요. 설명을 듣지 않아도 건축을 감상할 수 있어 언어 부담이 적습니다.\n\n현재도 예배가 열리는 성당입니다. 예배 시간에 관광객이 자유롭게 내부를 관람할 수 있다는 뜻은 아닙니다. 이 안내에서는 외관 관람을 기본으로 소개합니다. 이후 전쟁 기념물이나 가까운 민속악기 박물관으로 산책을 이어 갈 수 있습니다."
