        "bodyRu": "Зелёный базар интересен путешественнику как живой городской рынок. Здесь можно познакомиться с молочными продуктами, сухофруктами, сладостями и другими товарами, сравнивая ассортимент разных прилавков. Такая прогулка помогает понять повседневные привычки города, но не заменяет экскурсию о кухне и не предполагает, что любой продавец сможет объяснить состав продукта на иностранном языке.\n\nПеред покупкой уточняйте, относится ли цена к килограмму, упаковке или одной штуке. Попросите взвесить выбранное количество и заранее договоритесь о способе оплаты. Для продуктов важны условия хранения и перевозки; если планируете увезти покупку за границу, правила ввоза нужно проверить отдельно. При пищевых ограничениях не полагайтесь только на внешний вид товара.\n\nНа знакомство с торговыми рядами ориентировочно достаточно 45–90 минут. Это оценка для прогулки, без длительного обеда. Рынок можно соединить с парком Панфиловцев и внешним осмотром Центральной мечети. Расписания туристических справочников расходятся, поэтому посещение ранним утром или в понедельник лучше планировать после проверки актуального режима.",
