        "bodyRu": "Парк Первого Президента расположен в южной части Алматы и задуман как большое зелёное общественное пространство. В обычной прогулочной программе его выбирают ради открытых аллей, отдыха и знакомства с городскими пейзажами у предгорий. Однако сейчас решающим обстоятельством является не набор достопримечательностей внутри, а доступность территории.\n\nВ официальном сообщении от 8 сентября 2026 года говорится о полном закрытии парка на время реконструкции. Более ранняя информация о сохранении доступа к части территории больше не подходит для планирования посещения. Сообщение справочника об открытии в определённом месяце не является гарантированной датой: городская служба обещала объявить сроки отдельно.\n\nДо нового подтверждения парк следует оставлять в списке будущих мест, а не в расписании прогулки. В городском сообщении указан расположенный рядом Flow Park как альтернатива, но его собственный вход и текущие условия тоже проверяются отдельно. После открытия на спокойную прогулку можно ориентировочно выделить один–два часа. Не пересекайте строительные ограждения и не выбирайте маршрут через закрытую территорию.",
