        "zone": "Медеу / горы Алматы",
        "cardRu": "Шымбулак можно посещать ради горных видов и прогулки, а не только катания. Сначала выберите нужную линию канатной дороги и соответствующий пешеходный билет: базовый подъём и полный обзорный маршрут различаются. Доступность линий зависит от сезона, технического обслуживания и погоды, поэтому горный день планируйте с альтернативой.",
        "bodyRu": "Шымбулак — самостоятельный горный курорт, посещение которого лучше выделять в отдельную часть поездки. Для пешеходной программы сначала определите, до какой точки хотите подняться и что будете делать после прибытия. Базовый билет между Медеу и курортом не равен билету на все верхние линии. Прокат, обучение и другие сезонные услуги также не включаются автоматически.\n\nПеред выездом проверьте работу конкретных канатных дорог. Опубликованное сообщение о летнем сезоне до 18 октября 2026 года связано с поэтапным обслуживанием; оно не является расписанием на весь год. Реконструкция спортивного комплекса Медеу отдельно влияет на подъезд и парковку, поэтому доступ к курорту и возможность осмотреть каток нельзя считать одним условием.\n\nРедакционный ориентир для выбранной пешеходной программы — три–шесть часов без подтверждённого времени городской дороги. В горах нужны подходящая обувь и одежда с учётом прогноза. Оставьте возможность сократить подъём или заменить поездку городской программой. Не включайте высотный пеший маршрут в обычный билетный визит без отдельной подготовки.",
