        "zone": "Алматы",
        "cardRu": "Кок-Тобе добавляет к городской программе панораму Алматы и подъём над городом. Можно выбрать канатную дорогу или отдельный наземный способ, затем погулять по парку. Билеты на подъём и аттракционы оплачиваются раздельно. Во вторник канатная дорога открывается позднее; перед выездом проверяйте режим оператора.",
        "bodyRu": "Кок-Тобе удобен для знакомства с Алматы с высоты без организации полноценного горного похода. Основная программа проста: подъём, панорама и прогулка по территории. Колесо обозрения, скоростной спуск и другие развлечения выбираются дополнительно; их наличие не означает, что они включены в стоимость канатной дороги.\n\nПри планировании сначала определитесь со способом подъёма. Канатная дорога и пассажирский микроавтобус имеют разные тарифы и расписания. Адрес парка на вершине не является адресом нижней станции, а точку посадки и высадки наземного транспорта нужно уточнить отдельно. Для детского тарифа канатной дороги опубликовано требование документа о возрасте; условия для иностранного документа следует проверить до покупки.\n\nНа спокойный визит ориентировочно заложите полтора–три часа и запас на ожидание. По вторникам действует отдельное позднее открытие канатной дороги. Выбирая вечер, оставляйте время для обратного спуска и не привязывайте его к последнему возможному рейсу. Кок-Тобе хорошо завершает городской день, но не заменяет Шымбулак или маршрут в национальном парке.",
        "duration": "1,5–3 часа; редакционная оценка без длительного питания/аттракционов",
