        "zone": "центр/восток Алматы",
        "cardRu": "Центральная мечеть Алматы — религиозный и архитектурный объект на улице Пушкина. Начните с внешнего осмотра; посещение молитвенных помещений согласуйте на месте. Выбирайте сдержанную одежду, учитывайте молитвенное время и спрашивайте разрешение на фотографии. Для подъезда используйте уточнённую метку здания, а не общий ориентир центра.",
        "bodyRu": "Центральная мечеть Алматы позволяет познакомиться с религиозной архитектурой города. Для путешественника, который пришёл прежде всего посмотреть здание, разумно начать с фасада и разрешённой территории. Мечеть остаётся местом молитвы, поэтому туристическое посещение не следует воспринимать как свободный вход в музейные залы. Доступ внутрь и правила для немусульман нужно уточнять у сотрудников.\n\nВыбирайте одежду, закрывающую плечи и ноги; требования к головному убору и отдельным помещениям узнавайте на месте. Не фотографируйте молящихся без их согласия и не заходите в закрытые зоны. При плотном потоке посетителей лучше перенести осмотр, чем мешать богослужению. Опубликованные в справочниках часы не гарантируют доступ туристов во все помещения на протяжении дня.\n\nДля внешнего знакомства можно заложить примерно 20–40 минут. Это редакционный ориентир. Мечеть можно включить в отдельную прогулку после рынка, оставив запас на переходы. Правильный адресный ориентир — Пушкина, 16, у улицы Маметовой. Выбирайте метку самого здания, а место встречи и вход уточняйте отдельно.",
