        "zone": "север/центр Алматы",
        "cardRu": "Центральный парк подходит для спокойной прогулки и семейной программы с развлечениями. Вход в общественную территорию и отдельные аттракционы — разные вещи: парк сообщает о свободном доступе, а услуги выбираются и оплачиваются отдельно. Работу открытых развлечений уточняйте с учётом сезона и погоды.",
        "bodyRu": "Центральный парк отдыха — вариант для путешественника, которому хочется сделать паузу между музеями и городскими переездами. Здесь можно выбрать обычную прогулку по аллеям или добавить семейные развлечения. На сайте парка перечислены разные зоны, включая детские аттракционы, озеро и сезонные активности. Не обязательно покупать все доступные услуги: сначала определите, ради чего вы пришли.\n\nОператор разделяет свободный доступ к общественной территории и работу аттракционов. Их расписание зависит от погоды, сезона и условий эксплуатации. Круглосуточный доступ к парку не означает, что вечером или ночью работают кассы, прокат и водные развлечения. Для конкретной услуги нужен отдельный тариф и проверка возрастных либо ростовых ограничений.\n\nДля прогулки с одной–двумя остановками можно ориентировочно выделить от одного до трёх часов. Зоопарк рядом следует считать самостоятельным посещением с отдельным входом и билетом. При поездке с детьми не перегружайте день сразу несколькими большими территориями. Покажите водителю адрес парка на улице Гоголя, 1, и заранее договоритесь, у какого входа вас забрать.",
