            "ko": "중앙공원에서는 일정을 가볍게 잡아도, 활동을 더해도 좋습니다. 산책만 할지 놀이시설을 이용할지 동행자와 먼저 이야기해 보세요. 정해진 시간 안에 모든 시설을 방문하려 하기보다 관심 있는 몇 가지를 고르는 편이 편안합니다.\n\n어린이와 함께한다면 이용 조건을 확인한 뒤 티켓을 구매하세요. 놀이시설과 워터파크에는 각각 요금과 운영 시간이 있습니다. 공원에 들어갈 수 있는 시간에 모든 시설이 운영하는 것은 아니며, 날씨에 따라 이용이 달라질 수 있습니다.\n\n인근 동물원은 별도 입구와 입장권을 사용하는 다른 방문지입니다. 같은 날 함께 둘러보려면 충분한 시간을 확보하세요. 짧게 방문할 때는 활동을 많이 넣기보다 공원을 걷는 시간 자체를 즐겨도 좋습니다."
