        "cardRu": "Национальный центральный музей помогает составить исторический и культурный контекст поездки. Выберите самостоятельный осмотр или экскурсию и проверьте именно пакет для иностранного посетителя. Музей закрыт по вторникам, касса заканчивает работу раньше залов. Язык экскурсии и аудиогида уточняйте отдельно: корейское сопровождение не подтверждено.",
        "bodyRu": "Национальный центральный музей Республики Казахстан полезно посетить в начале поездки, если хочется лучше понимать культурные объекты, которые встретятся дальше. Программа может быть самостоятельной или экскурсионной. Сначала определите интересующие темы и доступные залы: попытка быстро пройти всю экспозицию не всегда помогает сохранить впечатления.\n\nОператор публикует отдельные пакеты для иностранных граждан. В их описании указаны все залы, поэтому к такому билету нельзя автоматически прибавлять оплату отдельных экспозиций из других тарифных категорий. Для экскурсии перечислены казахский, русский и английский языки; корейское сопровождение в доступном источнике не подтверждено. Онлайн-партнёры могут показывать цену, отличающуюся от кассы.\n\nДля самостоятельного знакомства ориентировочно заложите два–три часа. Во вторник музей закрыт, а касса завершает работу раньше залов. Не ставьте поздний подъезд впритык к её закрытию. Адрес — Самал-1, 44. После осмотра удобно продолжить городскую программу, но время следующего переезда рассчитывайте по фактической точке, а не по общему слову «центр».",
