        "zone": "Алматы",
        "cardRu": "Алматинский зоопарк — самостоятельная семейная программа рядом с Центральным парком. Выберите интересующие павильоны и двигайтесь по карте территории, оставляя время на отдых. Входной билет и доступность отдельных экспозиций проверяйте отдельно: санитарные дни павильонов не означают закрытие всего зоопарка. Касса закрывается раньше территории.",
        "bodyRu": "Алматинский зоопарк подходит для отдельного городского дня или его значительной части. Посещение удобнее строить вокруг нескольких интересующих групп животных, а не пытаться быстро пройти все экспозиции. На сайте оператора есть карта территории: используйте её, чтобы заранее выбрать последовательность павильонов и не возвращаться несколько раз по одному пути.\n\nЧасы кассы заканчиваются раньше общего времени посещения. Кроме того, у отдельных павильонов есть собственные санитарные дни; открытый зоопарк не гарантирует доступность каждого помещения. Перед визитом проверьте нужную экспозицию, особенно если ради неё организуется семейная поездка. Тарифы для детей и взрослых отличаются, а льготы могут требовать документов. Возрастные границы на опубликованной странице пересекаются, поэтому билет для ребёнка пограничного возраста уточняйте до оплаты.\n\nРедакционный ориентир для неспешного осмотра — два–четыре часа. Не планируйте столь же большой обход Центрального парка сразу следом, если дети быстро устают. Для подъезда используйте адрес Есенберлина, 166, и отличайте вход в зоопарк от соседних парковых ворот.",
