        "zone": "Алматы",
        "cardRu": "Музей искусств имени Кастеева стоит выбрать для знакомства с художественной традицией Казахстана. Рассмотрите постоянную коллекцию и проверьте текущие выставки, прежде чем покупать билет. Музейный день требует отдельного планирования: понедельник и последний день месяца указаны среди дней, когда обычное посещение недоступно.",
        "bodyRu": "Национальный музей искусств имени Абылхана Кастеева — хороший выбор для путешественника, который хочет познакомиться с Казахстаном через визуальное искусство. Перед посещением посмотрите, какие постоянные залы и временные выставки открыты. Такой подход помогает выбрать программу по интересам: живопись, другие виды изобразительного искусства или конкретная выставка, а не просто обходить все помещения подряд.\n\nНа самостоятельное знакомство можно ориентировочно выделить полтора–три часа. Для вдумчивого просмотра одной темы иногда полезнее меньше залов, но больше времени у работ. Если нужна экскурсия, отдельно уточните доступные языки и входит ли она в выбранный билет. Опубликованные льготные категории связаны с подтверждающими документами; применимость льгот к иностранному посетителю не следует предполагать автоматически.\n\nВ официальном FAQ указаны выходной понедельник, санитарный последний день месяца и окончание работы кассы раньше закрытия музея. Проверяйте также специальные изменения и временные выставки. Адрес в Коктем-3 отличается от дома-музея художника: при заказе транспорта выберите именно основной художественный музей, чтобы не приехать в другой объект.",
