        "cardRu": "Иле-Алатауский национальный парк — большая горная территория с разными долинами и маршрутами. Выбирайте конкретную тропу и проверяйте её вход, сложность, доступ и условия оплаты. Адрес администрации не является туристическим входом. Для первого выезда лучше одна посильная программа, чем несколько ущелий за один день.",
        "bodyRu": "Иле-Алатауский национальный парк объединяет разные природные пространства у Алматы: лесные участки, ущелья, водопады и высокогорные объекты. План поездки начинается не с общего названия парка, а с выбора конкретного маршрута. От него зависят дорога, точка входа, пешая нагрузка, связь и возможность возвращения до темноты.\n\nВ каталоге маршрутов парка есть варианты разной сложности. Для первого знакомства выбирайте программу по силам участников и фактическим погодным условиям. Не воспринимайте административную метку на карте как начало тропы: офис находится в городе и не описывает все туристические участки. Также нельзя переносить режим или плату одного ущелья на всю территорию.\n\nОпубликованный в старом FAQ расчёт платы относится к указанному там году и не используется здесь как текущая цена. Уточняйте действующий сбор и дополнительные услуги для выбранного участка. Время прогулки, обувь и снаряжение подбираются под маршрут. Если его состояние или доступ не подтверждены, выбирайте другую программу, а не пытайтесь пройти по непроверенной тропе.",
