        "zone": "центр Алматы",
        "cardRu": "Театр имени Абая добавляет к поездке вечер оперы или балета. Выберите конкретный спектакль по официальной афише, проверьте язык и наличие субтитров, затем покупайте билет на нужную дату. Экскурсия по театру и представление — разные программы; одна не входит автоматически в стоимость другой.",
        "bodyRu": "Казахский национальный театр оперы и балета имени Абая стоит включать в поездку через конкретное событие. Для первого посещения сравните официальную афишу, время начала и характер постановки. Опера и балет дают разные впечатления; язык исполнения и наличие субтитров особенно важны для путешественника, который не понимает русский или казахский.\n\nБилет покупается на выбранное представление и место в зале. Не рассчитывайте на одну постоянную цену театра: она зависит от события и категории места. Также не обещайте посещение музейной части или экскурсию на основании билета на спектакль. Эти программы следует уточнять отдельно у оператора.\n\nВечер лучше оставить свободным от дальнего выезда. Заранее предусмотрите прибытие, гардероб и поиск места, а после окончания — возвращение к проживанию. Длительность задаётся конкретной постановкой, поэтому в каталоге нет универсального двухчасового расписания. Адрес — Кабанбай батыра, 110. Днём можно рассмотреть здание снаружи, но такой осмотр не заменяет полноценного посещения представления.",
