        "cardRu": "Музей имени Ыхласа знакомит с музыкальными инструментами Казахстана в историческом деревянном здании у парка Панфиловцев. Рассмотрите домбру, кобыз и другие инструменты, а дополнительные программы выбирайте по афише. Часы работы в источниках расходятся: перед посещением подтвердите режим непосредственно у музея. Концерт не включён автоматически.",
        "bodyRu": "Музей народных музыкальных инструментов имени Ыхласа — отдельная культурная остановка в районе парка Панфиловцев. Здесь внимание сосредоточено на музыкальном наследии: формы инструментов, материалы и способы извлечения звука помогают увидеть традицию с другой стороны, чем живопись или историческая экспозиция. Среди представленных типов инструментов — домбра, кобыз и другие образцы, связанные с музыкой Казахстана и народов мира.\n\nДля первого визита полезно выбрать несколько залов и рассмотреть их спокойно. Если хотите услышать инструменты в исполнении, ищите конкретную концертную или образовательную программу: наличие коллекции не означает ежедневный живой концерт. Язык экскурсии, возможность аудиосопровождения и условия фотографирования уточняются отдельно.\n\nНа самостоятельный осмотр ориентировочно заложите 45–90 минут, затем продолжите прогулку по парку. Адрес — Зенкова, 24а. Источники содержат разные часы: старый государственный каталог и обновлённые страницы оператора не совпадают. Поэтому в плане дня оставьте альтернативу и подтвердите режим до поездки. Указанная в каталоге цена не заменяет проверку текущего билета.",
