            "ko": "이흘라스 민속악기 박물관에서는 돔브라와 코비즈 등 여러 악기를 통해 카자흐스탄의 음악 문화를 만날 수 있습니다. 모양과 재료를 천천히 살펴보세요. 판필로프 공원과 가까우며, 실제 연주 프로그램과 현재 운영 시간은 별도로 확인해야 합니다."
