        "bodyRu": "Главный ботанический сад отличается от обычного городского парка: это природоохранная и научная территория с живыми коллекциями растений. Для путешественника он подходит как спокойная программа между насыщенными городскими днями. Выбирайте прогулку по интересующим участкам, обращая внимание на таблички и устройство коллекций. Экскурсия может сделать осмотр содержательнее, но её нужно согласовывать отдельно.\n\nУ сада несколько входов, поэтому место начала и окончания прогулки лучше выбрать заранее. Северный и западный входы находятся со стороны Тимирязева, южный — со стороны Аль-Фараби. Метка одного входа не описывает все остальные. На выбранную часть территории ориентировочно заложите полтора–три часа, учитывая сезон и возможность отдыха.\n\nОператор указывает санитарный первый понедельник месяца и отдельный режим касс. В контактной информации также отмечена реконструкция оранжереи, поэтому обещать посещение тропической коллекции сейчас нельзя. Не сходите с разрешённых дорожек и не повреждайте растения. Для организованной съёмки или специальных программ проверяйте условия отдельно от обычного входного билета.",
