        "zone": "площадь Республики, Алматы",
        "cardRu": "Монумент Независимости на площади Республики — короткая остановка для знакомства с символами современного Казахстана. Рассмотрите фигуру Золотого воина и скульптурные группы у основания. Посещение удобно соединить с прогулкой по соседним улицам. Доступ к площади может меняться во время мероприятий, поэтому не назначайте встречу внутри перекрытой зоны.",
        "bodyRu": "Монумент Независимости расположен на площади Республики и связан с историей современного Казахстана. Центральный образ — Золотой воин на высокой колонне; у основания находятся скульптурные группы. Для самостоятельного путешественника место интересно как открытая городская композиция, которую можно рассмотреть без посещения музейных залов.\n\nНачните с общего вида, затем подойдите к доступным элементам у основания. Описание символики лучше читать спокойно, не превращая остановку только в фотографию из машины. На такой осмотр можно ориентировочно заложить 20–40 минут. Если проходит городское событие, схема прохода и место высадки могут измениться: публичная площадь не означает свободный доступ к каждой её части в любой момент.\n\nМонумент удобно обсуждать вместе с Национальным центральным музеем как две разные формы знакомства со страной. При этом путь между ними проверяется отдельно. Для встречи с водителем выбирайте разрешённую точку у площади, а не остановку непосредственно возле памятника. Место подходит для короткой культурной паузы, но не заменяет подробную историческую экспозицию.",
