            "ko": "공화국 광장을 걷다가 독립 기념비에 잠시 들러 보세요. 기둥 위의 황금 인간상과 주변 조각을 함께 살펴볼 수 있습니다. 짧은 외부 관람으로도 일정에 넣기 좋지만, 도시 행사 때는 광장 출입이 달라질 수 있습니다."
