            "ko": "먼저 광장 안에서 기념비의 전체 모습을 바라보고 주변 조각으로 가까이 다가가 보세요. 기둥 위의 황금 인간상과 아래의 조형물은 서로 다른 방향에서 살펴볼 수 있습니다. 관심을 끄는 세부에 잠시 머물러도 좋습니다.\n\n별도의 실내 전시를 방문하는 일정과 달리 광장 산책 중 외부에서 둘러보는 장소입니다. 중앙박물관 등 주변 방문지와 함께 계획한다면 실제 이동 거리를 비교해 순서를 정하세요.\n\n도시 행사에 따라 광장 일부의 통행이 제한될 수 있습니다. 차량은 허용된 위치에서 내려야 하며 기념비 바로 앞까지 접근할 수 있다고 생각해서는 안 됩니다. 관람과 주변 산책에 짧은 여유를 두면 일정이 한결 편안해집니다."
