        "cardRu": "Большое Алматинское озеро — природное направление с отдельными условиями доступа. Красивые виды не означают свободный подъезд к берегу или разрешение на любую прогулку. Перед планированием уточните текущий режим дороги и разрешённый маршрут. При неизвестном доступе оставьте озеро в списке будущих поездок, а не в расписании дня.",
        "bodyRu": "Большое Алматинское озеро стоит рассматривать как отдельную природную поездку, а не короткую остановку между городскими достопримечательностями. Для подготовки важнее всего установить действующий способ доступа: где можно ехать, где разрешён пеший проход и какая точка доступна для осмотра. По фотографиям и старым отзывам эти вопросы решить нельзя.\n\nНа сайте Иле-Алатауского парка есть сообщение о временном закрытии автодороги из-за камнепада и состояния покрытия. В доступном материале не установлена дата, поэтому сообщение сохраняется как предупреждение для проверки, а не как доказанный текущий запрет на любой визит. При этом возможность пешего доступа из него тоже не следует.\n\nДо подтверждения условий не назначайте точное время выезда, подъезда или прогулки вдоль берега. Выбирайте программу только по разрешённым участкам и учитывайте изменение погоды в горах. Старые рекламные предложения подъехать на машине не являются гарантией. Если информация о доступе противоречива, перенесите поездку и используйте городской либо курортный вариант с понятными условиями.",
        "duration": "Отдельный выезд; длительность не назначена до проверки доступа и дороги",
