        "cardRu": "Dostyk Plaza удобно использовать как практическую остановку для покупок, еды или кино. Это торговый центр, а не историческая достопримечательность. Выберите нужный сервис и проверьте его собственное расписание: магазины, супермаркет, кафе и кинотеатр работают по разным часам, даже находясь в одном здании.",
        "bodyRu": "Dostyk Plaza помогает решить практические задачи во время городской поездки: сделать покупки, поесть или выбрать фильм. Центр лучше включать в программу по конкретной необходимости, а не ставить на один уровень с музеями и природными маршрутами. Посмотрите список магазинов и услуг заранее, чтобы не тратить весь день на поиск нужного этажа.\n\nНа официальном сайте отдельно указаны часы торгового центра, супермаркета, кинотеатра и части кафе. Поэтому время закрытия одного оператора не описывает весь комплекс. Для кино важны сеанс, язык и условия билета; для покупок — ассортимент конкретного магазина. Наличие иностранного бренда не означает, что цена или выбор товаров будут такими же, как в другой стране.\n\nРедакционный ориентир для обычной остановки — один–три часа без долгого сеанса. Если после неё планируется горный выезд, учитывайте время подъезда и пробки. Место встречи с водителем согласуйте по конкретному выходу. Оплата товаров, парковки и развлечений относится к отдельным услугам, а не к одной универсальной стоимости визита в торговый центр.",
