        "categoryRu": "религиозное место",
        "zone": "Алматы",
        "cardRu": "Никольский собор — отдельный действующий православный храм Алматы, который не следует путать с Вознесенским собором в парке Панфиловцев. Его можно выбрать для спокойного архитектурного осмотра. Доступ внутрь, расписание служб и фотосъёмку уточняйте у прихода; обычный туристический визит не должен мешать богослужению.",
        "bodyRu": "Свято-Никольский собор интересен тем, кто хочет расширить знакомство с религиозной архитектурой Алматы за пределы самого известного храма в парке Панфиловцев. Это другой объект в другой части города. При поиске и заказе транспорта используйте полное название прихода: одинаковое слово «собор» не гарантирует правильную точку назначения.\n\nПрограмму можно начать с внешнего осмотра здания и разрешённой территории. Для внутреннего посещения учитывайте службы и обращайтесь к сотрудникам с вопросами о правилах. Спокойная одежда, тихое поведение и согласование фотографий помогают избежать неудобства для прихожан. Возможность пройти внутрь в конкретное время не следует выводить из общей карточки справочника.\n\nРедакционный ориентир для короткого осмотра — 30–60 минут без участия в богослужении. Выбирайте храм как самостоятельную остановку, если он соответствует интересам поездки, а не как обязательное дополнение к каждому городскому дню. Официальный сайт прихода и материалы митрополии дают контекст и церковные новости; актуальную доступность для туристов уточняйте отдельно от опубликованного времени службы.",
        "duration": "30–60 минут; редакционная оценка без участия в богослужении",
