            "ru": "Никольский собор можно включить в прогулку, если вам интересны храмы Алматы. Рассмотрите здание снаружи и, при разрешённом доступе, продолжите знакомство внутри. Визит проходит в действующем религиозном пространстве. Правила осмотра и фотосъёмки нужно учитывать на месте.",
            "ko": "알마티의 종교 건축에 관심이 있다면 니콜라이 대성당을 산책 일정에 더할 수 있습니다. 먼저 외관을 살펴보고 출입이 허용될 때 내부를 둘러보세요. 현재도 사용되는 성당이므로 관람과 사진 촬영 규칙을 따르는 것이 중요합니다."
