        "cardRu": "Чарынский каньон выбирайте как отдельный природный день. В национальном парке есть несколько маршрутов; для первого визита определите конкретный участок, например Долину замков. Проверяйте вход, дорогу, разрешённый пеший путь и возвращение. Поездку не следует автоматически объединять с Кольсаем и Каинды только потому, что они находятся в одной области.",
        "bodyRu": "Чарынский национальный парк интересен разнообразием природных участков, поэтому перед поездкой важно выбрать конкретную цель. Долина замков — отдельный маршрут, а ясеневая роща и другие каньоны требуют собственной логистики. Общая метка парка или адрес его управления не является точкой входа в выбранный участок.\n\nДля первого визита разумно выделить полноценный день и согласовать с перевозчиком место высадки, продолжительность пешей части и время обратного выезда. Это редакционная рекомендация, а не подтверждённое расписание тура. Точное время городской дороги и актуальный тариф парка в пакете не подменены данными случайного туристического сайта.\n\nНа открытых природных участках учитывайте прогноз, запас воды, головной убор и обувь для неровного покрытия. Не планируйте возвращение после темноты, если программа рассчитана на дневной осмотр. Если нужны дополнительные услуги внутри парка, уточните их отдельно от входной платы. Кольсай и Каинды не добавляйте как обязательные остановки того же дня: такой план должен иметь отдельную проверку дороги, нагрузки и времени.",
