        "bodyRu": "Esentai Mall стоит рассматривать как отдельную торговую и сервисную остановку. Оператор описывает его как центр с магазинами, ресторанами и развлечениями, в том числе брендами высокого ценового сегмента. Перед визитом полезно понять, нужен ли конкретный магазин, место для обеда или программа на вечер: это помогает выбрать разумную продолжительность остановки.\n\nАдрес торгового центра — проспект Аль-Фараби, 77/8. На сайте указан общий режим 10:00–22:00, но отдельное заведение или событие может иметь свои условия. Для кино и ресторанов проверяйте конкретное расписание, язык и бронирование. Не предполагайте наличие нужного товара только по присутствию бренда в списке.\n\nНа обычный осмотр и покупки ориентировочно выделите один–два часа. Такая остановка может быть удобна между программами, но не должна создавать лишний переезд через город. Для обратной встречи договоритесь о выходе и разрешённой зоне посадки. Стоимость парковки, еды и развлечений рассматривается отдельно: единой цены, описывающей весь визит, у торгового центра нет.",
