        "zone": "Иле-Алатау, Алматы",
        "cardRu": "Горельник — направление для горной прогулки, где сначала нужно выбрать конкретную тропу. Не путайте ущелье с одноимённым визит-центром: его часы и услуги не описывают доступность всего маршрута. До похода проверьте состояние тропы, нагрузку и точку старта, оставив запас на возвращение при изменении погоды.",
        "bodyRu": "Название Горельник может относиться к ущелью, водопадам, маршруту и коммерческому визит-центру. Для путешественника это разные цели поездки. Если хочется пройти по природной тропе, не ограничивайтесь адресом кафе или центра: нужно знать начало разрешённого маршрута, его длину, перепад высот и место возвращения.\n\nНациональный парк упоминает Горельник среди туристических маршрутов и мест для походов. Но общий список не подтверждает состояние конкретной тропы в день поездки. А найденная карточка 2ГИС относится к визит-центру на улице Керей-Жанибек хандар, поэтому указанное там время работы не является расписанием ущелья.\n\nВыбирайте пешую программу с учётом опыта группы и прогноза. До старта проверьте карту, условия прохода и возможность связи, согласуйте обратную встречу с водителем. Не обещайте посещение водопадов как простую прогулку, если фактическая тропа и её сложность не проверены. При неопределённости ограничьтесь известной разрешённой зоной отдыха или замените поход другим направлением. В каталоге нет вымышленного времени подъёма.",
        "duration": "По конкретной тропе; длительность похода не подтверждена",
