        "zone": "окрестности Алматы",
        "cardRu": "Oi-Qaragai — горный курорт с разными сезонными услугами. Выберите программу заранее: прогулка, подъём, активность или отдых с проживанием требуют разных продуктов. Круглосуточная работа части комплекса не означает непрерывную работу подъёмников. Уточните конкретный билет, возрастные условия и обратный транспорт, не ориентируясь на одну общую цену курорта.",
        "bodyRu": "Oi-Qaragai, известный также как Лесная Сказка, удобно рассматривать как отдельный курортный выезд. Главное при планировании — выбрать конкретную услугу, а не искать универсальную стоимость посещения. Пешеходный подъём, спортивный абонемент, занятия с инструктором и проживание относятся к разным продуктам и могут иметь разный режим.\n\nВ правилах оператора отдельно описываются подъёмники, прокат, услуги и схема территории. Перед оплатой проверьте, какие возможности включает выбранный билет и какие документы нужны для возрастной категории. Не переносите зимний тариф обучения на летнюю прогулку и не считайте круглосуточность гостиничной части расписанием канатных дорог.\n\nДля спокойной программы можно ориентировочно выделить половину или весь день, но фактическая длительность зависит от выбранных занятий. Согласуйте транспорт и точку обратной встречи, особенно если планируется вечернее возвращение. Адрес для корреспонденции оператора не заменяет туристическую точку высадки. Посмотрите актуальную карту курорта и ограничения по погоде. Суммы старых сезонных прайсов в каталоге не используются как единая действующая цена.",
