        "zone": "Алматинская область",
        "cardRu": "Кольсайские озёра — самостоятельное природное направление, а не один короткий городской выезд. Начните с выбора конкретного озера и посильной прогулки. Более дальние участки требуют отдельной подготовки. Дорогу, входные условия и ночёвку согласуйте заранее; Каинды можно обсуждать как дополнительный вариант после проверки логистики.",
        "bodyRu": "Кольсайские озёра находятся в национальном парке «Көлсай көлдері». Важно различать Нижний, Средний и Верхний Кольсай: поездка к одному озеру не означает, что все остальные доступны в той же программе. Для первого знакомства разумно выбрать конкретную береговую прогулку и не добавлять продолжительный поход без отдельной подготовки.\n\nПланируйте направление как самостоятельный выезд. Дорога к выбранной точке, возможности местного транспорта и обратный путь требуют согласования. Редакционный ориентир в один–два дня помогает отделить такую поездку от городской прогулки, но не заменяет проверку фактического маршрута. Если предполагается ночёвка, заранее уточните размещение и время второго дня.\n\nНациональный парк описывает природные объекты и разные активности, однако их доступность зависит от конкретной программы и сезона. Не переносите цену проката, прогулки на лодке или конного маршрута на входной билет. Каинды относится к тому же парку, но требует собственного подъезда. Добавляйте его только после проверки последнего участка дороги, запаса времени и возможностей участников.",
