        "bodyRu": "Озеро Каинды — отдельный природный объект национального парка «Көлсай көлдері». Его узнаваемая особенность — стволы затопленных елей, выступающие над водой. Для осмотра важна не только фотография места, но и точная программа посещения: подъезд, разрешённый пеший участок, условия дороги и возвращение к транспорту.\n\nНе считайте Каинды продолжением любой поездки к Кольсаю без дополнительного планирования. Точки находятся в разных ущельях, а последнее плечо пути требует собственной проверки. Если перевозчик предлагает местный транспорт, заранее уточните, где происходит пересадка, что включено в оплату и сколько времени остаётся на прогулку. В пакете не обещается свободный подъезд легковой машины к берегу.\n\nВыбирайте обувь с учётом неровного и влажного покрытия, следите за прогнозом и доступностью разрешённых участков. Фотографируйте с открытых для посетителей точек, не заходя в закрытые зоны ради другого ракурса. Поездку можно обсуждать вместе с Кольсаем и ночёвкой, но конкретный план должен учитывать оба подъезда, а не только общую длительность тура.",
