        "bodyRu": "Медеу важно различать как спортивный комплекс, горный район и ориентир для поездки к Шымбулаку. Эти названия часто встречаются вместе, однако билет на канатную дорогу не является платой за каток, а кафе с похожим названием не заменяет информацию оператора комплекса. Такое разделение особенно важно при заказе трансфера и выборе места встречи.\n\nВ официальных городских сообщениях говорится о реконструкции комплекса и плановом завершении работ в четвёртом квартале 2027 года. Это план, а не гарантия открытия. Отдельно опубликовано ограничение близлежащей парковки. Поэтому прежние часы катания, тарифы льда и обещание прогулки внутри комплекса нельзя использовать как действующие сведения.\n\nЕсли район нужен только для пересадки на канатную дорогу, сначала проверьте текущую схему подъезда у курорта и согласуйте высадку с водителем. Внешний осмотр допустим лишь там, где разрешён проход: не заходите в строительные зоны ради фотографии. Для программы, связанной с самим катком, держите городскую альтернативу. Срок и длительность внутреннего посещения в текущем каталоге намеренно не назначены.",
